<x-app-layout>
    <style>
        .taxonomy-screen{max-width:1240px;margin:0 auto;padding:20px 22px 34px;color:#1f2937}.taxonomy-head{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:12px}.taxonomy-head h1{margin:0;font-size:24px;font-weight:800}.taxonomy-head p{margin:3px 0 0;color:#64748b;font-size:13px}.taxonomy-layout{display:grid;grid-template-columns:minmax(250px,3fr) minmax(0,5fr);gap:16px;align-items:start}.taxonomy-layout.trash{grid-template-columns:1fr}.taxonomy-card{border:1px solid #e5caca;border-radius:10px;background:#fff7f7;box-shadow:0 4px 16px rgba(127,29,29,.05)}.taxonomy-create{position:sticky;top:16px;padding:16px}.taxonomy-card h2{margin:0 0 12px;font-size:17px}.taxonomy-field{display:grid;gap:5px;margin-bottom:10px}.taxonomy-field label{font-size:11px;font-weight:800;color:#374151}.taxonomy-input,.taxonomy-textarea,.taxonomy-select{width:100%;min-height:36px;border:1px solid #d8b4b4;border-radius:7px;background:#fff;padding:7px 9px;color:#111827}.taxonomy-textarea{min-height:76px;resize:vertical}.taxonomy-row{display:grid;grid-template-columns:1fr 100px;gap:8px}.taxonomy-help{margin:-3px 0 9px;color:#64748b;font-size:10px;line-height:1.45}.taxonomy-button{display:inline-flex;align-items:center;justify-content:center;min-height:35px;border:0;border-radius:7px;background:#a90000;padding:0 13px;color:#fff;font-size:12px;font-weight:800;cursor:pointer}.taxonomy-button:disabled{opacity:.42;cursor:not-allowed}.taxonomy-button.secondary{border:1px solid #d8b4b4;background:#fff;color:#8b0000}.taxonomy-button.danger{border:1px solid #efb5b5;background:#fff;color:#b91c1c}.taxonomy-list{padding:12px}.taxonomy-empty{padding:28px;text-align:center;color:#64748b}.taxonomy-item{overflow:hidden;border:1px solid #efd4d4;border-radius:8px;background:#fff;margin-bottom:7px}.taxonomy-item summary{display:grid;grid-template-columns:58px 44px minmax(0,1fr) auto;align-items:center;gap:10px;padding:9px 11px;cursor:pointer;list-style:none}.taxonomy-item summary: