ight:48px;object-fit:cover;border:1px solid #dcdcde}.media-selected-preview span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:560px}@media(max-width:850px){.taxonomy-layout{grid-template-columns:1fr}.taxonomy-create{position:static}.taxonomy-editor-grid,.taxonomy-row{grid-template-columns:1fr}.taxonomy-editor .wide{grid-column:auto}.media-body{min-height:320px}.taxonomy-bulkbar{align-items:flex-start;flex-direction:column}}
