    <div class="media-modal" id="category-media-modal" aria-hidden="true" role="dialog" aria-modal="true" aria-labelledby="category-media-title">
        <div class="media-panel">
            <div class="media-head"><strong id="category-media-title">Media Library</strong><button class="taxonomy-button secondary" type="button" id="category-media-close">Close</button></div>
            <div class="media-tabs"><button type="button" class="is-active" data-media-tab="upload">Upload files</button><button type="button" data-media-tab="library">Media Library</button></div>
            <div class="media-body">
                <div class="media-panel-view" data-media-panel="upload"><div class="media-upload-drop"><strong>Drop files to upload</strong><span>or</span><button type="button" class="taxonomy-button secondary" id="category-media-select-file">Select image</button><input type="file" id="category-media-file" accept=".png,.jpg,.jpeg,.webp,.gif,.ico" hidden><div class="media-upload-status" id="category-media-upload-status">Selecting an image uploads it immediately.</div></div></div>
                <div class="media-panel-view" data-media-panel="library" hidden><div class="media-library" id="category-media-library"><p class="taxonomy-help">Open the library to load existing media.</p></div></div>
            </div>
            <div class="media-foot"><div class="media-selected-preview" id="category-selected-media">Select or upload an image.</div><button class="taxonomy-button" type="button" id="category-media-use" disabled>Use image</button></div>
        </div>
    </div>

    <script>
        (()=>{
            const csrf=@json(csrf_token());
            const routes={mediaIndex:@json(route('admin.media.index', [], false)),mediaStore:@json(route('admin.media.store', [], false))};
            const map={'ا':'a','أ':'a','إ':'i','آ':'a','ب':'b','ت':'t','ث':'th','ج':'j','ح':'h','خ':'kh','د':'d','ذ':'dh','ر':'r','ز':'z','س':'s','ش':'sh','ص':'s','ض':'d','ط':'t','ظ':'z','ع':'a','غ':'gh','ف':'f','ق':'q','ك':'k','ل':'l','م':'m','ن':'n','ه':'h','ة':'a','و':'w','ؤ':'w','ي':'y','ى':'a','ئ':'y'};
            const slugify=value=>Array.from(value).map(char=>map[char]??char).join('').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
            const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
            let targetForm=null,selectedMedia=null,libraryLoaded=false,libraryLoading=false;
            const modal=document.getElementById('category-media-modal'),library=document.getElementById('category-media-library'),useButton=document.getElementById('category-media-use'),details=document.getElementById('category-selected-media');

            document.querySelectorAll('[data-slug-pair]').forEach(form=>{const name=form.querySelector('[data-name-input]');const slug=form.querySelector('[data-slug-input]');if(!name||!slug)return;let manual=slug.value.trim()!=='';slug.addEventListener('input',()=>manual=slug.value.trim()!=='');name.addEventListener('input',()=>{if(!manual)slug.value=slugify(name.value)});});
            if(location.hash){const item=document.querySelector(location.hash);if(item?.tagName==='DETAILS')item.open=true;}

            function activateTab(name){document.querySelectorAll('[data-media-tab]').forEach(tab=>tab.classList.toggle('is-active',tab.dataset.mediaTab===name));document.querySelectorAll('[data-media-panel]').forEach(panel=>panel.hidden=panel.dataset.mediaPanel!==name);if(name==='library')loadLibrary();}
            function openMedia(button){targetForm=button.closest('form');selectedMedia=null;useButton.disabled=true;details.textContent='Select or upload an image.';activateTab('upload');modal.classList.add('is-open');modal.setAttribute('aria-hidden','false');}
            function closeMedia(){modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true');}
            function selectTile(tile){document.querySelectorAll('.media-tile').forEach(item=>item.classList.remove('is-selected'));tile.classList.add('is-selected');selectedMedia={url:tile.dataset.url,title:tile.dataset.title||'',alt:tile.dataset.alt||''};useButton.disabled=false;details.innerHTML=`<img src="${escapeHtml(selectedMedia.url)}" alt=""><span><strong>${escapeHtml(selectedMedia.title||'Image')}</strong><br>${escapeHtml(selectedMedia.url)}</span>`;}
            function makeTile(media,prepend=false){const help=library.querySelector('.taxonomy-help');if(help)help.remove();const tile=document.createElement('button');tile.type='button';tile.className='media-tile';tile.dataset.url=media.url;tile.dataset.title=media.title||media.name||'';tile.dataset.alt=media.alt_text||'';tile.innerHTML=`<img src="${escapeHtml(media.url)}" alt="${escapeHtml(media.alt_text||'')}"><small>${escapeHtml(media.title||media.name||'Image')}</small>`;tile.addEventListener('click',()=>selectTile(tile));prepend?library.prepend(tile):library.appendChild(tile);return tile;}
            async function loadLibrary(){if(libraryLoaded||libraryLoading)return;libraryLoading=true;library.innerHTML='<p class="taxonomy-help">Loading media...</p>';try{const response=await fetch(routes.mediaIndex,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error();const data=await response.json();library.innerHTML='';(data.items||[]).forEach(item=>makeTile(item));if(!library.children.length)library.innerHTML='<p class="taxonomy-help">No images are available in the media library yet.</p>';libraryLoaded=true;}catch(error){library.innerHTML='<p class="taxonomy-help">Media library could not be loaded. Upload a new image or try again.</p>';}finally{libraryLoading=false;}}
            async function uploadMedia(){const input=document.getElementById('category-media-file'),file=input.files[0],status=document.getElementById('category-media-upload-status');if(!file)return;status.textContent='Uploading...';const form=new FormData();form.append('image',file);form.append('title',file.name.replace(/\.[^.]+$/,''));try{const response=await fetch(routes.mediaStore,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'},body:form});const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{})[0]?.[0]||'Upload failed.');activateTab('library');const tile=makeTile(data.media,true);selectTile(tile);libraryLoaded=false;status.textContent='Uploaded. Use the image or choose another one.';}catch(error){status.textContent=error.message||'Upload failed. Please choose a valid image up to 4 MB.';}finally{input.value='';}}
            function useMedia(){if(!selectedMedia||!targetForm)return;targetForm.querySelector('[data-category-image]').value=selectedMedia.url;const alt=targetForm.querySelector('[name="image_alt"]');if(alt&&!alt.value)alt.value=selectedMedia.alt;targetForm.querySelector('[data-category-preview]').innerHTML=`<img src="${escapeHtml(selectedMedia.url)}" alt="">`;const remove=targetForm.querySelector('[data-remove-category-image]');if(remove)remove.checked=false;closeMedia();}

            document.querySelectorAll('[data-category-media]').forEach(button=>button.addEventListener('click',()=>openMedia(button)));
            document.querySelectorAll('[data-remove-category-image]').forEach(input=>input.addEventListener('change',()=>{if(input.checked){const form=input.closest('form');form.querySelector('[data-category-image]').value='';form.querySelector('[data-category-preview]').innerHTML='';}}));
            document.querySelectorAll('[data-media-tab]').forEach(tab=>tab.addEventListener('click',()=>activateTab(tab.dataset.mediaTab)));
            document.getElementById('category-media-close').addEventListener('click',closeMedia);document.getElementById('category-media-select-file').addEventListener('click',()=>document.getElementById('category-media-file').click());document.getElementById('category-media-file').addEventListener('change',uploadMedia);useButton.addEventListener('click',useMedia);modal.addEventListener('click',event=>{if(event.target===modal)closeMedia();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modal.classList.contains('is-open'))closeMedia();});
            const categoryRows=[...document.querySelectorAll('[data-category-row]')],categoryAll=[...document.querySelectorAll('[data-category-select-all]')],categoryButtons=[...document.querySelectorAll('[data-category-bulk]')],categoryAction=document.getElementById('categories-bulk-action'),categoryForm=document.getElementById('categories-bulk-form');
            function refreshCategoryBulk(){const count=categoryRows.filter(row=>row.checked).length;categoryButtons.forEach(button=>button.disabled=count===0);categoryAll.forEach(all=>{all.checked=count>0&&count===categoryRows.length;all.indeterminate=count>0&&count<categoryRows.length;});}
            categoryRows.forEach(row=>row.addEventListener('change',refreshCategoryBulk));categoryAll.forEach(all=>all.addEventListener('change',()=>{categoryRows.forEach(row=>row.checked=all.checked);refreshCategoryBulk();}));categoryButtons.forEach(button=>button.addEventListener('click',()=>{categoryAction.value=button.dataset.categoryBulk;categoryForm.requestSubmit();}));refreshCategoryBulk();
        })();
    </script>
</x-app-layout>
